import { test } from '@playwright/test';
import { ADMIN_STATE, expectStampsInViewport, openInboxChat, openTicketDetail, setEnglish } from './support-helpers';

test.use({ storageState: ADMIN_STATE, timezoneId: 'Asia/Jerusalem' });

test.describe('Поддержка — дата и время сообщений (#3db49a08)', () => {
  test('Message timestamps stay inside the screen on Android on ticket detail and Support Console #3db49a08 @android @prod-safe', async ({ page }) => {
    await setEnglish(page);

    // Шаг 1: экран обращения
    await openTicketDetail(page);
    await expectStampsInViewport(page);

    // Шаг 2: Support Console → Chat → QA-обращение
    await openInboxChat(page);
    await expectStampsInViewport(page);
  });
});
